package local.station.controller;
import android.content.Context;import android.net.*;import java.net.*;
/** Bind a private target only to its actual directly attached LAN, never an unrelated Wi-Fi. */
final class LanNetwork {
 static org.json.JSONObject state(Context context,String host){org.json.JSONObject j=new org.json.JSONObject();try{boolean wifi=false,vpn=false,lan=false;ConnectivityManager cm=(ConnectivityManager)context.getSystemService(Context.CONNECTIVITY_SERVICE);for(Network n:cm.getAllNetworks()){NetworkCapabilities c=cm.getNetworkCapabilities(n);if(c==null)continue;vpn|=c.hasTransport(NetworkCapabilities.TRANSPORT_VPN);wifi|=c.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)||c.hasTransport(NetworkCapabilities.TRANSPORT_ETHERNET);}if(host!=null&&!host.isEmpty()){byte[] target=InetAddress.getByName(host).getAddress();java.util.Enumeration<NetworkInterface> all=NetworkInterface.getNetworkInterfaces();while(all.hasMoreElements()){NetworkInterface n=all.nextElement();if(!n.isUp()||n.isLoopback()||n.getName().matches("(?i).*(tun|vpn|ccmni|rmnet).*"))continue;for(InterfaceAddress a:n.getInterfaceAddresses()){if(!(a.getAddress() instanceof Inet4Address)||!a.getAddress().isSiteLocalAddress())continue;byte[] ip=a.getAddress().getAddress();int bits=a.getNetworkPrefixLength();boolean match=bits>0;for(int k=0;k<4;k++){int take=Math.max(0,Math.min(8,bits-k*8)),mask=take==0?0:255<<(8-take);if((ip[k]&mask)!=(target[k]&mask))match=false;}lan|=match;}}}j.put("wifi",wifi).put("vpn",vpn).put("matchingLan",lan);}catch(Exception ignored){}return j;}
 static Network find(Context context,String host){try{InetAddress target=InetAddress.getByName(host);if(!(target instanceof Inet4Address)||!target.isSiteLocalAddress())return null;ConnectivityManager cm=(ConnectivityManager)context.getSystemService(Context.CONNECTIVITY_SERVICE);Network chosen=null;int longest=-1;for(Network n:cm.getAllNetworks()){NetworkCapabilities caps=cm.getNetworkCapabilities(n);LinkProperties props=cm.getLinkProperties(n);if(caps==null||props==null||!caps.hasCapability(NetworkCapabilities.NET_CAPABILITY_NOT_RESTRICTED)||caps.hasTransport(NetworkCapabilities.TRANSPORT_VPN)||!(caps.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)||caps.hasTransport(NetworkCapabilities.TRANSPORT_ETHERNET)))continue;for(LinkAddress local:props.getLinkAddresses()){if(!(local.getAddress() instanceof Inet4Address))continue;int bits=local.getPrefixLength();byte[] a=target.getAddress(),b=local.getAddress().getAddress();boolean match=true;for(int i=0;i<4;i++){int take=Math.max(0,Math.min(8,bits-i*8)),mask=take==0?0:(255<<(8-take))&255;if((a[i]&mask)!=(b[i]&mask)){match=false;break;}}if(match&&bits>longest){try(Socket probe=new Socket()){n.bindSocket(probe);chosen=n;longest=bits;}catch(Exception denied){/* A VPN may forbid direct bindings; leave routing to Android. */}}}}return chosen;}catch(Exception ignored){}return null;}
 static URLConnection open(Context context,URL url)throws Exception{Network n=find(context,url.getHost());return n==null?url.openConnection(java.net.Proxy.NO_PROXY):n.openConnection(url,java.net.Proxy.NO_PROXY);}
}
